mapper.select:
SELECT
    CART_ID AS cartId,
    QUANTITY AS quantity
FROM CART
WHERE USER_ID = #{userId}
  AND PRODUCT_ID = #{productId}
  AND CART_TYPE = #{cartType}
  AND CART_ID != #{cartId}
  AND IFNULL(OPTION_ITEM_ID, 0) = IFNULL(#{optionItemId}, 0)


    AND IFNULL(RENTAL_START, '1000-01-01') = IFNULL(NULLIF(#{rentalStart}, ''), '1000-01-01')
    AND IFNULL(RENTAL_END, '1000-01-01') = IFNULL(NULLIF(#{rentalEnd}, ''), '1000-01-01')


LIMIT 1

SELECT
    poiv.OPTION_ITEM_ID
FROM PRODUCT_OPTION_ITEM_VALUE poiv
JOIN PRODUCT_OPTION_ITEM poi
    ON poiv.OPTION_ITEM_ID = poi.OPTION_ITEM_ID
WHERE poi.PRODUCT_ID = #{productId}
  AND poiv.OPTION_VALUE_ID IN

      #{id}

GROUP BY poiv.OPTION_ITEM_ID
HAVING COUNT(DISTINCT poiv.OPTION_VALUE_ID) = #{optionCount}
   AND (
       SELECT COUNT(*)
       FROM PRODUCT_OPTION_ITEM_VALUE x
       WHERE x.OPTION_ITEM_ID = poiv.OPTION_ITEM_ID
   ) = #{optionCount}
LIMIT 1

